import os
import re
from collections import defaultdict

ROOT = "/bench/repo"

# Patterns for direct store.Memo struct references (not MemoRelation, MemoShare, etc.)
def is_memo_type_ref(text, prefix):
    """Check if prefix.Memo or unqualified Memo is the struct type reference."""
    # prefix can be '' for unqualified, or 'store', or alias
    if prefix:
        pat = rf'\b{re.escape(prefix)}\.Memo\b(?![A-Za-z_])'
    else:
        # unqualified Memo - must not be part of another identifier
        pat = r'(?<![A-Za-z0-9_\.])\*?Memo\b(?![A-Za-z_])'
    return bool(re.search(pat, text))

def strip_comments_and_strings(line):
    # crude but helps avoid comment false positives
    s = line
    # remove // comments
    if '//' in s:
        s = s[:s.index('//')]
    return s

def get_import_alias(lines):
    alias = None
    for line in lines:
        m = re.match(r'\s*(?:(\w+)\s+)?"github\.com/usememos/memos/store"', line)
        if m:
            alias = m.group(1) or 'store'
            break
    return alias

packages = defaultdict(lambda: {"files": set(), "examples": []})

for dirpath, dirnames, filenames in os.walk(ROOT):
    # skip proto gen mostly - different Memo
    if '/proto/' in dirpath:
        continue
    for fn in filenames:
        if not fn.endswith('.go'):
            continue
        path = os.path.join(dirpath, fn)
        rel = os.path.relpath(path, ROOT)

        with open(path, 'r', errors='replace') as f:
            content = f.read()
            lines = content.splitlines()

        # get package dir
        pkg_dir = os.path.dirname(rel)

        # determine package name from file
        pkg_match = re.search(r'^package\s+(\w+)', content, re.M)
        if not pkg_match:
            continue
        pkg_name = pkg_match.group(1)

        alias = get_import_alias(lines)
        in_store_pkg = (pkg_dir == 'store' or pkg_dir.startswith('store/'))

        # For store subpackages (db/mysql etc), they import parent store package
        # Check each line for references
        refs = []
        for i, line in enumerate(lines, 1):
            clean = strip_comments_and_strings(line)

            if in_store_pkg and pkg_dir == 'store':
                # root store package - unqualified Memo
                if is_memo_type_ref(clean, ''):
                    # exclude type definition line
                    if re.search(r'\btype\s+Memo\s+struct\b', clean):
                        continue
                    refs.append((i, line.strip()[:100]))
            elif alias:
                if is_memo_type_ref(clean, alias):
                    refs.append((i, line.strip()[:100]))

        if refs:
            packages[pkg_dir]["files"].add(rel)
            if len(packages[pkg_dir]["examples"]) < 3:
                packages[pkg_dir]["examples"].extend(refs[:3-len(packages[pkg_dir]["examples"])])

for pkg in sorted(packages.keys()):
    info = packages[pkg]
    print(f"=== {pkg} ({len(info['files'])} files) ===")
    for f in sorted(info['files'])[:5]:
        print(f"  {f}")
    if len(info['files']) > 5:
        print(f"  ... +{len(info['files'])-5} more")
    for ln, ex in info['examples'][:2]:
        print(f"    L{ln}: {ex}")
    print()
